section.source:
final HtmlInput input = (HtmlInput) page.getElementById("i1");

final Keyboard kb = new Keyboard();
kb.press(KeyboardEvent.DOM_VK_CONTROL);
kb.type('c');
kb.release(KeyboardEvent.DOM_VK_CONTROL);
input.type(kb);

subsection.source:
final Keyboard kb = new Keyboard();

// press 'a' and 'b' and release them in the same order:
// keydown a, keypress a, input, keydown b, keypress b, input, keyup a, keyup b
kb.keyDown('a');
kb.keyDown('b');
kb.keyUp('a');
kb.keyUp('b');

// hold the arrow left key while typing 'x'
kb.keyDown(KeyboardEvent.DOM_VK_LEFT);
kb.type('x');
kb.keyUp(KeyboardEvent.DOM_VK_LEFT);

input.type(kb);

final Keyboard kb = new Keyboard();

// the right shift key: code is 'ShiftRight', location is 2
kb.keyDown(KeyboardEvent.DOM_VK_SHIFT, KeyboardEvent.DOM_KEY_LOCATION_RIGHT);
kb.type('A');
kb.keyUp(KeyboardEvent.DOM_VK_SHIFT, KeyboardEvent.DOM_KEY_LOCATION_RIGHT);

input.type(kb);

final Keyboard kb = new Keyboard();

// shift is still pressed
kb.setPressedModifiers(true, false, false, false);
kb.type('B');
kb.release(KeyboardEvent.DOM_VK_SHIFT);

input.type(kb);

section.source:
final Keyboard kb = new Keyboard();

// Select all
kb.press(KeyboardEvent.DOM_VK_CONTROL);
kb.type('a');
kb.release(KeyboardEvent.DOM_VK_CONTROL);

// Copy
kb.press(KeyboardEvent.DOM_VK_CONTROL);
kb.type('c');
kb.release(KeyboardEvent.DOM_VK_CONTROL);

input.type(kb);

final Keyboard kb = new Keyboard();

// Paste
kb.press(KeyboardEvent.DOM_VK_CONTROL);
kb.type('v');
kb.release(KeyboardEvent.DOM_VK_CONTROL);

input.type(kb);
